"""Measure the artificial memorization of finetune.py: GSSCD (content) and OFS-k (motion) of videos generated by the
fine-tuned model. See section 10 of README.md.

Steps:
  python memorization_eval.py prompts     the memorized captions, and as many random background captions
  python main.py --model outputs/finetune/final batch ...     generate one video per caption
  python memorization_eval.py metrics     GSSCD and OFS-k of every video, and the averages
  python memorization_eval.py plot        figures of the results

Both metrics are from Chen et al., "Investigating Memorization in Video Diffusion Models". Every generated video is
compared with the exact clip it was fine-tuned on: the 16 frames of finetune.py's read_clip, center-cropped.
"""
import argparse
import math
import os
import re

import numpy as np
import pandas as pd
import torch
import torch.nn.functional as F
from torchvision.models.optical_flow import Raft_Large_Weights, raft_large
from tqdm import tqdm

from finetune import read_clip
from sscd import load_sscd
from webvid import embed, gif_frames, square, video_path

SSCD_SIZE = 288  # SSCD's evaluation size, as in `webvid.py gsscd`
FLOW_SIZE = 256  # the size of the fine-tuning; RAFT needs a multiple of 8


# ------------------------------------------------------------------------------------------------------------------
# Part 1: the captions to generate
# ------------------------------------------------------------------------------------------------------------------

def run_prompts(args):
    """Write the sheet for `main.py batch`: every memorized sample once, and the same number of random background
    samples. The index is the videoid, so each generated video is named after the training video it should match."""
    table = pd.read_csv(args.table, keep_default_na=False)
    memorized = table[table["role"] == "memorized"]
    background = table[table["role"] == "background"].sample(n=len(memorized), random_state=args.seed)
    sheet = pd.concat([memorized, background]).rename(columns={"videoid": "index"})
    sheet = sheet[["index", "caption", "role", "copies"]]
    assert sheet["index"].is_unique and sheet["caption"].is_unique  # the table of finetune.py guarantees this
    os.makedirs(args.out, exist_ok=True)
    out = os.path.join(args.out, "prompts.csv")
    sheet.to_csv(out, index=False)
    print(f"{len(memorized)} memorized + {len(background)} background captions -> {out}")


# ------------------------------------------------------------------------------------------------------------------
# Part 2: the metrics
# ------------------------------------------------------------------------------------------------------------------

@torch.no_grad()
def optical_flow(raft, frames):
    """RAFT flow between consecutive frames. frames: [n, 3, H, W] in [0, 1] -> flows [n - 1, 2, H, W] on the GPU.
    A generated video has one frame per 4 frames of its training video, and read_clip takes the same stride, so the
    flows of both videos cover the same amount of time."""
    x = frames.cuda() * 2 - 1  # RAFT takes [-1, 1]
    return torch.cat([raft(x[:-1][i:i + 8], x[1:][i:i + 8])[-1] for i in range(0, len(x) - 1, 8)])  # [-1]: final estimate


def flow_similarity(generated, training):
    """S (Eq. 3): S[i, j] is the cosine similarity of the flow vectors of generated flow i and training flow j, averaged
    over the pixels. generated: [a, 2, H, W], training: [b, 2, H, W] -> [a, b]."""
    g = F.normalize(generated, dim=1).flatten(1)  # unit vector at every pixel; a zero vector stays zero
    t = F.normalize(training, dim=1).flatten(1)
    pixels = generated.shape[2] * generated.shape[3]
    return g @ t.T / pixels


def natural_motion(flow, min_magnitude, min_entropy, bins=36):
    """The natural motion filter of the paper: which flows to ignore, [n] bool. Static: the mean flow length is small.
    Camera panning: nearly all the pixels move in the same direction, so the entropy of the histogram of the flow angles
    is low. The paper does not give the thresholds or the bins; the entropy here is divided by its largest value, so
    it goes from 0 (one direction) to 1 (all directions equally)."""
    magnitude = flow.norm(dim=1).flatten(1).mean(1)
    angle = torch.atan2(flow[:, 1], flow[:, 0]).flatten(1)  # in [-pi, pi]
    index = ((angle + math.pi) / (2 * math.pi) * bins).long().clamp(0, bins - 1)
    p = torch.stack([torch.bincount(row, minlength=bins) for row in index]).float()
    p = p / p.sum(1, keepdim=True)
    entropy = -(p * p.clamp_min(1e-12).log()).sum(1) / math.log(bins)
    return (magnitude < min_magnitude) | (entropy < min_entropy)


def ofs_k(S, k, ignored_generated=None, ignored_training=None):
    """OFS-k (Eq. 4): the best average of S over k consecutive flows of both videos, over all the alignments of the two
    windows. With the natural motion filter, a window that contains an ignored flow does not count (the paper does not
    say how the filter enters Eq. 4). NaN if no window is left."""
    a, b = S.shape
    ignored_generated = torch.zeros(a, dtype=torch.bool) if ignored_generated is None else ignored_generated.cpu()
    ignored_training = torch.zeros(b, dtype=torch.bool) if ignored_training is None else ignored_training.cpu()
    best = float("nan")
    for i in range(a - k + 1):
        if ignored_generated[i:i + k].any():
            continue
        for j in range(b - k + 1):
            if ignored_training[j:j + k].any():
                continue
            score = S[range(i, i + k), range(j, j + k)].mean().item()
            best = score if math.isnan(best) else max(best, score)
    return best


def summarize(df, by, ofs):
    """Mean, median and share of memorized videos of both metrics, per group."""
    return df.groupby(by).agg(
        videos=("videoid", "size"),
        gsscd_mean=("gsscd", "mean"), gsscd_median=("gsscd", "median"), gsscd_memorized=("gsscd_memorized", "mean"),
        ofs_mean=(ofs, "mean"), ofs_median=(ofs, "median"), ofs_memorized=(f"{ofs}_memorized", "mean"),
        ofs_nmf_videos=(f"{ofs}_nmf", "count"), ofs_nmf_mean=(f"{ofs}_nmf", "mean"),
        ofs_nmf_median=(f"{ofs}_nmf", "median"), ofs_nmf_memorized=(f"{ofs}_nmf_memorized", "mean"))


def run_metrics(args):
    """GSSCD and OFS-k of every generated video against its training clip -> metrics.csv, summary_role.csv and
    summary_copies.csv in --out."""
    if not 1 <= args.k <= 15:
        raise SystemExit("--k must be between 1 and 15: 16 frames have 15 flows")
    sheet = pd.read_csv(os.path.join(args.out, "prompts.csv"), keep_default_na=False).rename(columns={"index": "videoid"})
    gif = lambda v: os.path.join(args.videos, f"{v}.gif")
    missing = [v for v in sheet["videoid"] if not os.path.exists(gif(v))]
    if missing:  # averages over part of the videos could not be compared
        raise SystemExit(f"{len(missing)} of {len(sheet)} videos are not generated yet in {args.videos}")

    sscd = load_sscd(args.sscd_weights if os.path.exists(args.sscd_weights) else None)
    raft = raft_large(weights=Raft_Large_Weights.DEFAULT).cuda().eval()

    ofs = f"ofs_{args.k}"
    rows = []
    for row in tqdm(sheet.itertuples(), total=len(sheet), desc="metrics"):
        generated = gif_frames(gif(row.videoid))
        training = read_clip(video_path(args, row.videoid))

        # GSSCD (Eq. 2): the largest SSCD cosine similarity over all the pairs of frames.
        g = embed(sscd, square(generated, SSCD_SIZE, crop=False)).float()
        t = embed(sscd, square(training, SSCD_SIZE, crop=True)).float()
        gsscd = (g @ t.T).max().item()

        # OFS-k, without and with the natural motion filter (the paper reports both).
        fg = optical_flow(raft, square(generated, FLOW_SIZE, crop=False))
        ft = optical_flow(raft, square(training, FLOW_SIZE, crop=True))
        S = flow_similarity(fg, ft)
        filtered = ofs_k(S, args.k, natural_motion(fg, args.min_magnitude, args.min_entropy),
                         natural_motion(ft, args.min_magnitude, args.min_entropy))

        rows.append({"videoid": row.videoid, "role": row.role, "copies": row.copies, "caption": row.caption,
                     "gsscd": gsscd, ofs: ofs_k(S, args.k), f"{ofs}_nmf": filtered})

    df = pd.DataFrame(rows)
    df["gsscd_memorized"] = df["gsscd"] >= args.gsscd_threshold
    df[f"{ofs}_memorized"] = df[ofs] > args.ofs_threshold
    df[f"{ofs}_nmf_memorized"] = df[f"{ofs}_nmf"] > args.ofs_threshold  # a video with no window left counts as False

    df.to_csv(os.path.join(args.out, "metrics.csv"), index=False, float_format="%.4f")
    by_role = summarize(df, "role", ofs)
    by_copies = summarize(df[df["role"] == "memorized"], "copies", ofs)  # does memorization grow with the copies?
    by_role.to_csv(os.path.join(args.out, "summary_role.csv"), float_format="%.4f")
    by_copies.to_csv(os.path.join(args.out, "summary_copies.csv"), float_format="%.4f")
    with pd.option_context("display.width", 250, "display.max_columns", None, "display.max_rows", None):
        print(by_role.round(3), "\n", by_copies.round(3))
    print(f"-> {args.out}: metrics.csv, summary_role.csv, summary_copies.csv")


# ------------------------------------------------------------------------------------------------------------------
# Part 3: the figures
# ------------------------------------------------------------------------------------------------------------------

MEMORIZED_COLOR, BACKGROUND_COLOR = "#2a78d6", "#eb6834"
INK, MUTED, GRID = "#0b0b0b", "#52514e", "#e6e5e0"


def metric_panels(df, args):
    """What each panel of a figure shows: (column, title, threshold, share of videos counted as memorized per row)."""
    ofs = next(c for c in df.columns if re.fullmatch(r"ofs_\d+", c))
    k = ofs.split("_")[1]
    return [("gsscd", "GSSCD (content)", args.gsscd_threshold, df["gsscd"] >= args.gsscd_threshold),
            (ofs, f"OFS-{k} (motion)", args.ofs_threshold, df[ofs] > args.ofs_threshold),
            (f"{ofs}_nmf", f"OFS-{k} with natural motion filter", args.ofs_threshold, df[f"{ofs}_nmf"] > args.ofs_threshold)]


def legend_below(fig, ax):
    """One legend for all the panels, below them, so that it cannot cover the data."""
    handles, labels = ax.get_legend_handles_labels()
    fig.legend(handles, labels, frameon=False, ncol=len(labels), loc="lower center", fontsize=11)
    fig.tight_layout(rect=(0, 0.09, 1, 1))


def plot_distributions(df, panels, plt):
    """How the scores of the memorized and the background videos are spread."""
    fig, axes = plt.subplots(1, 3, figsize=(14, 4.4), sharey=False)
    bins = np.arange(-1, 1.0001, 0.05)
    for ax, (column, title, threshold, _) in zip(axes, panels):
        for role, color, label in [("memorized", MEMORIZED_COLOR, "Memorized"), ("background", BACKGROUND_COLOR, "Background")]:
            values = df.loc[df["role"] == role, column].dropna()
            ax.hist(values, bins=bins, histtype="step", linewidth=2, color=color, label=label)
            ax.hist(values, bins=bins, color=color, alpha=0.15)
        ax.axvline(threshold, color=MUTED, linestyle="--", linewidth=1.2, label="Threshold of the paper")
        ax.text(threshold, 0.99, f" {threshold:g}", transform=ax.get_xaxis_transform(), va="top", color=MUTED)
        ax.set_title(title, loc="left")
        counts = df.dropna(subset=[column])["role"].value_counts()
        ax.set_xlabel(f"Score (n = {counts['memorized']} memorized, {counts['background']} background)")
        ax.set_xlim(max(-1, df[column].min() - 0.05), 1)
    axes[0].set_ylabel("Videos")
    legend_below(fig, axes[0])
    return fig


def plot_copies(df, panels, plt):
    """Does the score grow with the number of copies? Every memorized video, the trend, and the background as reference."""
    memorized, background = df[df["role"] == "memorized"], df[df["role"] == "background"]
    levels = np.sort(memorized["copies"].unique())
    fig, axes = plt.subplots(1, 3, figsize=(14, 4.4), sharex=True)
    for ax, (column, title, threshold, _) in zip(axes, panels):
        # The trend: the mean of 5 neighbouring numbers of copies (a single level has only a few videos).
        trend = memorized.groupby("copies")[column].mean().reindex(levels).rolling(5, center=True, min_periods=1).mean()
        ax.scatter(memorized["copies"], memorized[column], s=22, color=MEMORIZED_COLOR, alpha=0.35, linewidths=0, label="One memorized video")
        ax.plot(levels, trend, color=MEMORIZED_COLOR, linewidth=2.5, label="Trend (mean over 5 levels)")
        ax.axhline(background[column].median(), color=BACKGROUND_COLOR, linewidth=2, label="Background median")
        ax.axhline(threshold, color=MUTED, linestyle="--", linewidth=1.2, label="Threshold of the paper")
        ax.text(0.995, threshold, f"{threshold:g}", transform=ax.get_yaxis_transform(), ha="right", va="bottom", color=MUTED,
                bbox=dict(facecolor="white", edgecolor="none", alpha=0.8, pad=1))
        ax.set_title(title, loc="left")
        ax.set_xlabel("Copies in the fine-tuning dataset")
        ax.set_ylim(min(-0.1, memorized[column].min() - 0.05), 1.05)
    axes[0].set_ylabel("Score")
    legend_below(fig, axes[0])
    return fig


def plot_share(df, panels, groups, plt):
    """The share of videos counted as memorized: the background, then the memorized videos grouped by their copies."""
    levels = np.array_split(np.sort(df.loc[df["role"] == "memorized", "copies"].unique()), groups)
    masks = [df["role"] == "background"] + [(df["role"] == "memorized") & df["copies"].isin(l) for l in levels]
    names = ["Background\n(1 copy)"] + [f"{l[0]}–{l[-1]}" for l in levels]
    colors = [BACKGROUND_COLOR] + [MEMORIZED_COLOR] * len(levels)
    fig, axes = plt.subplots(1, 3, figsize=(14, 4.4), sharey=True)
    for ax, (_, title, _, is_memorized) in zip(axes, panels):
        shares = [100 * is_memorized[m].mean() for m in masks]
        bars = ax.bar(names, shares, color=colors, width=0.72)
        ax.bar_label(bars, labels=[f"{s:.0f}%" for s in shares], padding=3, fontsize=11, color=INK)
        ax.set_title(title, loc="left")
        ax.set_xlabel("Copies in the fine-tuning dataset")
        ax.tick_params(axis="x", labelsize=10)
        ax.grid(False, axis="x")
    axes[0].set_ylabel("Videos counted as memorized (%)")
    axes[0].set_ylim(0, 112)
    fig.tight_layout(rect=(0, 0.05, 1, 1))
    fig.text(0.5, 0.01, "Share of all the videos of each group. With the filter, a video with no window left counts as not memorized.",
             ha="center", fontsize=11, color=MUTED)
    return fig


def plot_content_vs_motion(df, panels, plt):
    """Content and motion together: every video, with the counts in the four areas the two thresholds make."""
    (x, _, x_threshold, x_memorized), (y, _, y_threshold, y_memorized) = panels[:2]
    fig, ax = plt.subplots(figsize=(8, 6.2))
    for role, color, label in [("background", BACKGROUND_COLOR, "Background"), ("memorized", MEMORIZED_COLOR, "Memorized")]:
        rows = df["role"] == role
        ax.scatter(df.loc[rows, x], df.loc[rows, y], s=42, color=color, edgecolors="white", linewidths=0.8, label=label)
    ax.axvline(x_threshold, color=MUTED, linestyle="--", linewidth=1.2)
    ax.axhline(y_threshold, color=MUTED, linestyle="--", linewidth=1.2)
    ax.set_xlabel(panels[0][1])
    ax.set_ylabel(panels[1][1])
    ax.set_xlim(min(-0.08, df[x].min() - 0.03), 1)
    ax.set_ylim(min(-0.1, df[y].min() - 0.32), 1.2)  # room for the labels of the two lower areas
    # One label per area: how many memorized (M) and background (B) videos fall into it.
    bottom = ax.get_ylim()[0] + 0.02
    corners = [(False, True, ax.get_xlim()[0] + 0.015, 1.17, "left", "top", "Motion only"),
               (True, True, 0.985, 1.17, "right", "top", "Content and motion"),
               (False, False, ax.get_xlim()[0] + 0.015, bottom, "left", "bottom", "Neither"),
               (True, False, 0.985, bottom, "right", "bottom", "Content only")]
    for content, motion, tx, ty, ha, va, name in corners:
        rows = (x_memorized == content) & (y_memorized == motion)
        ax.text(tx, ty, f"{name}\nM {(rows & (df['role'] == 'memorized')).sum()}  ·  B {(rows & (df['role'] == 'background')).sum()}",
                ha=ha, va=va, fontsize=11, color=INK, bbox=dict(facecolor="white", edgecolor="none", alpha=0.85, pad=2))
    ax.legend(frameon=False, loc="center left", bbox_to_anchor=(1.0, 0.5))
    fig.tight_layout()
    return fig


def run_plot(args):
    """Figures of metrics.csv for presenting, as PNG (slides) and PDF (papers), in <--out>/plots."""
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    plt.rcParams.update({"font.size": 12, "axes.titlesize": 14, "text.color": INK, "axes.labelcolor": MUTED,
                         "xtick.color": MUTED, "ytick.color": MUTED, "axes.edgecolor": GRID, "axes.spines.top": False,
                         "axes.spines.right": False, "axes.grid": True, "grid.color": GRID, "grid.linewidth": 0.8,
                         "axes.axisbelow": True, "figure.facecolor": "white", "pdf.fonttype": 42})
    df = pd.read_csv(os.path.join(args.out, "metrics.csv"), keep_default_na=False, na_values=[""])
    panels = metric_panels(df, args)
    figures = {"distributions": plot_distributions(df, panels, plt), "score_vs_copies": plot_copies(df, panels, plt),
               "share_memorized": plot_share(df, panels, args.groups, plt), "content_vs_motion": plot_content_vs_motion(df, panels, plt)}
    folder = os.path.join(args.out, "plots")
    os.makedirs(folder, exist_ok=True)
    for name, fig in figures.items():
        for extension, dpi in [("png", 200), ("pdf", None)]:
            fig.savefig(os.path.join(folder, f"{name}.{extension}"), dpi=dpi, bbox_inches="tight")
        plt.close(fig)
    print(f"-> {folder}: {', '.join(figures)} (.png and .pdf)")


def main():
    parser = argparse.ArgumentParser(description="GSSCD and OFS-k of videos generated by the fine-tuned model")
    parser.add_argument("--root", default="data/webvid", help="the WebVid folder of webvid.py (where the videos are)")
    parser.add_argument("--out", default="outputs/finetune_eval", help="folder of the sheet and the results")
    sub = parser.add_subparsers(dest="command", required=True)

    p = sub.add_parser("prompts", help="write the sheet: the memorized samples and as many random background samples")
    p.add_argument("--table", default="outputs/finetune/finetune.csv", help="the table the model was fine-tuned on")
    p.add_argument("--seed", type=int, default=0, help="which background samples are drawn")

    m = sub.add_parser("metrics", help="GSSCD and OFS-k of the generated videos")
    m.add_argument("--videos", default="outputs/finetune_eval/normal", help="folder of the generated <videoid>.gif")
    m.add_argument("--k", type=int, default=3, help="flows per window of OFS-k (the paper's best: 3)")
    m.add_argument("--gsscd-threshold", type=float, default=0.4, help="GSSCD from which content is memorized (paper: 0.4)")
    m.add_argument("--ofs-threshold", type=float, default=0.5, help="OFS-k above which motion is memorized (paper: 0.5)")
    m.add_argument("--min-magnitude", type=float, default=0.5,
                   help="natural motion filter: mean flow length in pixels below which a flow is static (not in the paper)")
    m.add_argument("--min-entropy", type=float, default=0.5,
                   help="natural motion filter: direction entropy, 0 to 1, below which a flow is panning (not in the paper)")
    m.add_argument("--sscd-weights", default="data/webvid/models/sscd_disc_mixup.classy.pt",
                   help="SSCD weights; downloaded if missing")

    f = sub.add_parser("plot", help="figures of metrics.csv, in <--out>/plots")
    f.add_argument("--gsscd-threshold", type=float, default=0.4, help="line in the figures, and what counts as memorized")
    f.add_argument("--ofs-threshold", type=float, default=0.5, help="line in the figures, and what counts as memorized")
    f.add_argument("--groups", type=int, default=5, help="groups of copies in share_memorized")

    args = parser.parse_args()
    {"prompts": run_prompts, "metrics": run_metrics, "plot": run_plot}[args.command](args)


if __name__ == "__main__":
    main()
